  restored=root/'restored';backup.restore_backup(bundle,restored)
  assert block_ids(restored),'missing restored immutable blocks'
  with server(root,'restored') as (url,api):
   after=vector(api,'service:queued_tasks:sum{service="live"}',evaluation)
   assert after==before,'native independent restore lost the head sample'
  assert {str(p.relative_to(bundle)).replace('\\','/'):hashlib.sha256(p.read_bytes()).hexdigest() for p in bundle.rglob('*') if p.is_file() and p.name!='manifest.json'}==snapshot_files
  assert not list(root.glob('.snapshot-stage-*')),'staging directories leaked'
 finally:print('native lifecycle:',json.dumps(STATS))
